@triton.jit
def _tanh_value(x):
    # tanh(x) = 1 - 2 / (exp(2x) + 1), evaluated in fp32 opmath and rounded
    # once on store.  Saturates to +-1 without producing NaN and keeps NaN.
    y = 1.0 - 2.0 / (tl.exp(2.0 * x.to(tl.float32)) + 1.0)
    return y.to(x.dtype)


