@triton.jit
def _tanh_strided_kernel(
    ptr,
    n,
    N0: tl.constexpr,
    S0: tl.constexpr,
    N1: tl.constexpr,
    S1: tl.constexpr,
    N2: tl.constexpr,
    S2: tl.constexpr,
    N3: tl.constexpr,
    S3: tl.constexpr,
    N4: tl.constexpr,
    S4: tl.constexpr,
    N5: tl.constexpr,
    S5: tl.constexpr,
    N6: tl.constexpr,
    S6: tl.constexpr,
    N7: tl.constexpr,
    S7: tl.constexpr,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
    I64: tl.constexpr,
):
    pid = tl.program_id(0)
    if I64:
        idx = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
        nn = n.to(tl.int64)
        off = tl.zeros([BLOCK], dtype=tl.int64)
    else:
        idx = pid * BLOCK + tl.arange(0, BLOCK)
        nn = n
        off = tl.zeros([BLOCK], dtype=tl.int32)
    rem = idx
    # Dimensions are ordered innermost-first (smallest stride first) by the
    # host so the fastest-varying logical coordinate is the cheapest to walk.
